public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        StringBuilder builder = new StringBuilder();
        PatternLayout pattern = createPatternLayout();
        String patternString = pattern.getConversionPattern();
        for (int i = 0; i < patternString.length(); i++) {
            char currentChar = patternString.charAt(i);
            if (currentChar == '%') {
                i++;
                if (i >= patternString.length()) {
                    break;
                }
                char conversionChar = patternString.charAt(i);
                switch (conversionChar) {
                    case 'c':
                        builder.append(event.getLoggerName());
                        i = skipOption(patternString, i);
                        break;
                    case 'm':
                        builder.append(event.getMessage());
                        i = skipOption(patternString, i);
                        break;
                    case 't':
                        builder.append(Thread.currentThread().getName());
                        i = skipOption(patternString, i);
                        break;
                    case 'd':
                        String dateStr = DateUtils.formatDate(event.getTimeStamp(), "yyyy-MM-dd HH:mm:ss,SSS");
                        builder.append(dateStr);
                        i = skipDateOption(patternString, i, builder, event);
                        break;
                    case 'n':
                        // should not happen, but skip
                        i = skipOption(patternString, i);
                        break;
                    case 'p':
                        builder.append(event.getLevel().toString());
                        i = skipOption(patternString, i);
                        break;
                    case 'l':
                        LocationInfo locationInfo = event.getLocationInformation();
                        if (locationInfo != null) {
                            builder.append(locationInfo.getClassName())
                                  .append('.').append(locationInfo.getMethodName())
                                  .append('(').append(locationInfo.getFileName()).append(':').append(locationInfo.getLineNumber()).append(')');
                        }
                        i = skipOption(patternString, i);
                        break;
                    case 'r':
                        builder.append(System.currentTimeMillis() - event.getTimeStamp());
                        i = skipOption(patternString, i);
                        break;
                    case 'x':
                        builder.append(MDC.get("x") != null ? MDC.get("x") : "");
                        i = skipOption(patternString, i);
                        break;
                    case 'X':
                        builder.append(MDC.get("X") != null ? MDC.get("X") : "");
                        i = skipOption(patternString, i);
                        break;
                    case 'F':
                        builder.append(event.getFqcn());
                        i = skipOption(patternString, i);
                        break;
                    case 'M':
                        LocationInfo locInfo = event.getLocationInformation();
                        if (locInfo != null) {
                            builder.append(locInfo.getMethodName());
                        }
                        i = skipOption(patternString, i);
                        break;
                    case 'L':
                        LocationInfo locInfo2 = event.getLocationInformation();
                        if (locInfo2 != null) {
                            builder.append(locInfo2.getLineNumber());
                        }
                        i = skipOption(patternString, i);
                        break;
                    case 'e':
                        builder.append(System.getProperty("user.name"));
                        i = skipOption(patternString, i);
                        break;
                    case 'h':
                        builder.append(System.getProperty("host.name"));
                        i = skipOption(patternString, i);
                        break;
                    case 'a':
                        builder.append(System.getProperty("user.dir"));
                        i = skipOption(patternString, i);
                        break;
                    case 'c':
                        builder.append(event.getLoggerName());
                        i = skipOption(patternString, i);
                        break;
                    case '%':
                        builder.append('%');
                        break;
                    default:
                        builder.append('%').append(conversionChar);
                        break;
                }
            } else {
                builder.append(currentChar);
            }
        }
        return builder.toString();
    } catch (Exception e) {
        return "ERROR: " + e.getMessage();
    }
}

private int skipOption(String patternString, int currentIndex) {
    if (currentIndex + 1 < patternString.length() && patternString.charAt(currentIndex + 1) == '{') {
        int endBrace = patternString.indexOf('}', currentIndex + 1);
        if (endBrace != -1) {
            return endBrace;
        }
    }
    return currentIndex;
}

private int skipDateOption(String patternString, int currentIndex, StringBuilder builder, LoggingEvent event) {
    if (currentIndex + 1 < patternString.length() && patternString.charAt(currentIndex + 1) == '{') {
        int endBrace = patternString.indexOf('}', currentIndex + 1);
        if (endBrace != -1) {
            String dateFormat = patternString.substring(currentIndex + 2, endBrace);
            builder.setLength(builder.length() - builder.indexOf(DateUtils.formatDate(event.getTimeStamp(), "yyyy-MM-dd HH:mm:ss,SSS")));
            builder.append(DateUtils.formatDate(event.getTimeStamp(), dateFormat));
            return endBrace;
        }
    }
    return currentIndex;
}

private PatternLayout createPatternLayout() {
    // This is a simplified version, the actual implementation would be more complex
    return new PatternLayout("%d{yyyy-MM-dd HH:mm:ss,SSS} [%t] %p %c{1} - %m%n");
