public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    if (data.isEmpty()) {
        return;
    }
    METRICS merged = METRICS.EMPTY;
    for (Key key : data.keySet()) {
        METRICS.Value existingValue = getValue(key);
        METRICS.Value newValue = data.get(key);
        double mergedValue = 0;
        if (existingValue == null) {
            mergedValue = newValue.data();
        } else {
            mergedValue = existingValue.data() + newValue.data();
        }
        merged = merged.put(key, new METRICS.Value(mergedValue));
    }
    if (!merged.isEmpty()) {
        put(merged);
    }
}

void insertBefore(Bucket bucket) {
