        // bucket is the head
        this.right = bucket;
        this.left = null;
        bucket.left = this;
    } else {
        Bucket predecessor = bucket.left;
        this.left = predecessor;
        this.right = bucket;
        predecessor.right = this;
        bucket.left = this;
    }
