    return (code[offset] << 56) + ((code[offset + 1] & 0xFF) << 48) + ((code[offset + 2] & 0xFF) << 40) + ((code[offset + 3] & 0xFF) << 32) + ((code[offset + 4] & 0xFF) << 24) + ((code[offset + 5] & 0xFF) << 16) + ((code[offset + 6] & 0xFF) << 8) + (code[offset + 7] & 0xFF);
