public long readLong(final int offset) {
    final int i1 = b[offset] & 0xFF;
    final int i2 = b[offset + 1] & 0xFF;
    final int i3 = b[offset + 2] & 0xFF;
    final int i4 = b[offset + 3] & 0xFF;
    final int i5 = b[offset + 4] & 0xFF;
    final int i6 = b[offset + 5] & 0xFF;
    final int i7 = b[offset + 6] & 0xFF;
    final int i8 = b[offset + 7] & 0xFF;
    return ((long) i1 << 56)
            | ((long) i2 << 48)
            | ((long) i3 << 40)
            | ((long) i4 << 32)
            | ((long) i5 << 24)
            | ((long) i6 << 16)
            | ((long) i7 << 8)
            | (long) i8;
