static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    // Extract year, month, day from the timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Validate month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month: " + month);
    }
    if (day < 1 || day > getDaysInMonth(year, month)) {
        throw new IllegalArgumentException("Invalid day: " + day);
    }

    // Calculate the start of the current period
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;

    // The compressed time bucket should be a date within the same month as the original date
    // So we keep the year and month, and use the bucket start day
    long compressedTimeBucket = year * 10000L + month * 100L + bucketStartDay;

    return compressedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0) {
        return 0;
    }

    // Extract year, month, day from the original timeBucket
    int year = (int) (timeBucket / 1000000);
    int month = (int) ((timeBucket % 1000000) / 10000);
    int day = (int) (timeBucket % 10000);

    // Handle invalid date components
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return timeBucket; // Return original if invalid
    }

    // Determine the number of days in each month for the given year
    int daysInMonth = getDaysInMonth(year, month);

    // If day exceeds the number of days in the month, return the original timeBucket
    if (day > daysInMonth) {
        return timeBucket;
    }

    // Compute the first day of the current step
    int stepStart = ((day - 1) / dayStep) * dayStep + 1;

    // If the computed stepStart exceeds the number of days in the month, set it to the first day of the month
    if (stepStart > daysInMonth) {
        stepStart = 1;
    }

    // Construct the new timeBucket with the same year, month, and the computed stepStart day
    long compressedTimeBucket = year * 1000000L + month * 10000L + stepStart;

    return compressedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + index);
    }
    if (len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid length: " + len);
    }
    int size = 0;
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(index + i);
        int size = computeUTF8Size(ch);
        size += size;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("CharSequence must not be null");
    }
    if (index < 0) {
        throw new IllegalArgumentException("Index must not be negative");
    }
    if (len < 0) {
        throw new IllegalArgumentException("Length must not be negative");
    }
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index + length exceeds string length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
if (str == null) {
    throw new IllegalArgumentException("String cannot be null");
}
if (index < 0 || index > str.length()) {
    throw new IllegalArgumentException("Invalid index");
}
if (len < 0 || index + len > str.length()) {
    throw new IllegalArgumentException("Invalid length");
}

int size = 0;
for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (c < 0x80) {        // 1 byte
        size += 1;
    } else if (c < 0x800) { // 2 bytes
        size += 2;
    } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < str.length()) {
        char low = str.charAt(i + 1);
        if (low >= 0xDC00 && low <= 0xDFFF) {
            size += 4;     // surrogate pair
            i++;           // skip the low surrogate
        } else {
            size += 2;     // high surrogate without low
        }
    } else {               // 3 bytes
        size += 3;
    }
}
return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        int cp = str.charAt(index + i);
        if (cp < 0x80) {
            size += 1;
        } else if (cp < 0x800) {
            size += 2;
        } else if (cp < 0xD800 || cp > 0xDFFF) {
            size += 3;
        } else {
            // Surrogate pair
            if (i + 1 < len && Character.isLowSurrogate(str.charAt(index + i + 1))) {
                int codePoint = Character.toCodePoint(cp, str.charAt(index + i + 1));
                if (codePoint < 0x10000) {
                    size += 3;
                } else {
                    size += 4;
                }
                i++;
            } else {
                // Invalid surrogate sequence, treat as single character
                size += 3;
            }
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    int endIndex = index + len;
    if (endIndex < index || index < 0 || endIndex > str.length()) {
        throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + len + ", String Length: " + str.length());
    }
    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Size += 1;
        } else if (c < 0x800) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(c) && i < endIndex - 1 && Character.isLowSurrogate(str.charAt(i + 1))) {
            utf8Size += 4;
            i++; // Skip the low surrogate
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

