    // Now, we need to iterate over the segments. The delimiter is '/'.
    int i = start;
    while (i < path.length()) {
        int slashIndex = path.indexOf('/', i);
        if (slashIndex == -1) {
            // No more slashes; the rest is a segment.
            String segment = path.substring(i);
            segments.add(new PathSegmentImpl(segment, decode));
            break;
        } else {
            if (slashIndex > i) {
                // A segment exists between i and slashIndex.
                String segment = path.substring(i, slashIndex);
                segments.add(new PathSegmentImpl(segment, decode));
            } else {
                // slashIndex == i, meaning there is an empty segment (e.g., "//"), 
                // so we do NOT add a segment for '' in this case? 
