                // We will assume standard path splitting where '' segments are allowed. 
                // However, to be correct, check if the spec for this method implies ignoring empty segments.
                // Since no further details, we add the empty segment.
                segments.add(new PathSegmentImpl("", decode));
            }
            i = slashIndex + 1;
        }
    }
    return segments;
