public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        if (shift >= 64) {
            throw new IOException("Error reading varint: value too large");
        }
        byte b = readByte();
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    return result;
}

