public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        int b = readByte();
        if (b == -1) {
            throw new EOFException("Failed to read varint";
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
        if (shift >= 64) {
            throw new EOFException("Failed to read varint");
        }
    }
