public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        return 0;
    }
    // Compute total size first so caller can use the return value
    int size = 0;
    for (LinkedBuffer n = node; n != null; n = n.next) {
        if (n.onHeapBuffer != null) {
            size += n.onHeapBuffer.remaining();
        } else if (n.offHeapBuffer != null) {
            size += n.offHeapBuffer.remaining();
        }
    }

    // Now write the data
    for (LinkedBuffer n = node; n != null; n = n.next) {
        if (n.onHeapBuffer != null) {
            out.write(n.onHeapBuffer.array(), 
                      n.onHeapBuffer.arrayOffset() + n.onHeapBuffer.position(), 
                      n.onHeapBuffer.remaining());
            n.onHeapBuffer.position(n.onHeapBuffer.limit());
        } else if (n.offHeapBuffer != null) {
            // Direct buffers can't be accessed via array(), so write remaining bytes
            byte[] tmp = new byte[n.offHeapBuffer.remaining()];
            n.offHeapBuffer.get(tmp);
            out.write(tmp);
            // Note: position is advanced by get()
        }
    }

    return size;
}
