    // Append the thread name
    if (event.getThreadName() != null) {
        sb.append(" [").append(event.getThreadName()).append("] ");
    } else {
        sb.append(" [UNKNOWN THREAD] ");
    }

    // Append the message
    if (event.getMessage() != null) {
        sb.append(event.getMessage()).append(" ");
    } else {
        sb.append("[NO MESSAGE] ");
    }

    // Append exceptions/throwable if present
    if (event.getThrowable() != null) {
        sb.append("Exception: ").append(event.getThrowable().getMessage()).append("\n");
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        event.getThrowable().printStackTrace(pw);
        sb.append(sw.toString());
    }

    return sb.toString();
}
