public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch != '\\') {
            buf.append(ch);
            continue;
        }
        if (i + 1 >= len) {
            buf.append(ch);
            continue;
        }
        char nextChar = str.charAt(i + 1);
        switch (nextChar) {
            case 'b':
                buf.append('\b');
                i++;
                break;
            case 't':
                buf.append('\t');
                i++;
                break;
            case 'n':
                buf.append('\n');
                i++;
                break;
            case 'f':
                buf.append('\f');
                i++;
                break;
            case 'r':
                buf.append('\r');
                i++;
                break;
            case '\"':
                buf.append('\"');
                i++;
                break;
            case '\'':
                buf.append('\'');
                i++;
                break;
            case '\\':
                buf.append('\\');
                i++;
                break;
            case '0':
                buf.append('\0');
                i++;
                break;
            default:
                buf.append(ch);
                break;
        }
    }
    return buf.toString();
