public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder buf = new StringBuilder();
    int len = str.length();
    int i = 0;
    int c1;
    int c2 = 0;
    int temp = -1;
    do {
        if (i >= len) {
            break;
        }
        c1 = str.charAt(i++);
        if (c1 == '\\') {
            if (i == len) {
                break;
            }
            c2 = str.charAt(i++);
            switch (c2) {
                case '\'': {
                    buf.append('\'');
                    break;
                }
                case '"': {
                    buf.append('"');
                    break;
                }
                case '\\': {
                    buf.append('\\');
                    break;
                }
                case 'n': {
                    buf.append('\n');
                    break;
                }
                case 'r': {
                    buf.append('\r');
                    break;
                }
                case 't': {
                    buf.append('\t');
                    break;
                }
                case 'f': {
                    buf.append('\f');
                    break;
                }
                case 'b': {
                    buf.append('\b');
                    break;
                }
                case 'u': {
                    if (i < (len - 3)) {
                        try {
                            temp = hexToInt(str.charAt(i), 16)
                                   + hexToInt(str.charAt(i + 1), 16) * 16
                                   + hexToInt(str.charAt(i + 2), 16) * 16 * 16
                                   + hexToInt(str.charAt(i + 3), 16) * 16 * 16 * 16;
                            buf.append((char) temp);
                            i += 4;
                        } catch (IllegalArgumentException e) {
                            buf.append('\\');
                            buf.append('u');
                            buf.append(str.charAt(i));
                            buf.append(str.charAt(i + 1));
                            buf.append(str.charAt(i + 2));
                            buf.append(str.charAt(i + 3));
                            i += 4;
                        }
                    } else {
                        buf.append(c1);
                    }
                    break;
                }
                default: {
                    buf.append(c1);
                    buf.append(c2);
                }
            }
        } else {
            buf.append(c1);
        }
    } while (true);
    return buf.toString();
}

private static int hexToInt(char ch, int radix) {
    if (ch < '0' || ch > '9' && ch < 'a' || ch > 'f' && ch < 'A' || ch > 'F') {
        throw new IllegalArgumentException("Invalid character: " + ch);
    }
    int unicode = Character.digit(ch, radix);
    if (unicode == -1) {
        throw new IllegalArgumentException("Invalid character: " + ch);
    }
    return unicode;
}
