        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                buf.append(c);
                continue;
            }
            i++;
            char next = str.charAt(i);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'b':
                    buf.append('\b');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case '\\':
                    buf.append('\\');
                    break;
                case '\'':
                    buf.append('\'');
                    break;
                case '"':
                    buf.append('"');
                    break;
                case 'u':
                    long unicode = 0;
                    if (i + 4 < len) {
                        for (int j = 0; j < 4; j++) {
                            i++;
                            char hexChar = str.charAt(i);
                            int value = Character.digit(hexChar, 16);
                            if (value == -1) {
                                throw new IllegalArgumentException("Invalid unicode escape sequence: " + str.substring(i - 4, i));
                            }
                            unicode = (unicode << 4) | value;
                        }
                        buf.append((char) unicode);
                    } else {
                        buf.append('\\');
                        buf.append('u');
                    }
                    break;
                default:
                    buf.append('\\');
                    buf.append(next);
                    break;
            }
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
