    final int newLength = (array == null) ? 1 : ((Object[]) array).length + 1;
    final int newLengthType = newArrayComponentType.isPrimitive() ? 
            (newArrayComponentType == boolean.class) ? 1 : 
            (newArrayComponentType == byte.class) ? 2 : 
            (newArrayComponentType == short.class) ? 3 : 
            (newArrayComponentType == int.class) ? 4 : 
            (newArrayComponentType == long.class) ? 5 : 
            (newArrayComponentType == char.class) ? 6 : 
            (newArrayComponentType == float.class) ? 7 : 
            (newArrayComponentType == double.class) ? 8 : 9 : 9;
    final Object newArray;

    switch (newLengthType) {
        case 1: // boolean
            if (array == null) {
                newArray = new boolean[newLength];
            } else {
                boolean[] oldArray = (boolean[]) array;
                boolean[] newArrayBool = new boolean[newLength];
                System.arraycopy(oldArray, 0, newArrayBool, 0, oldArray.length);
