        case 4: // int
            if (array == null) {
                newArray = new int[newLength];
            } else {
                int[] oldArray = (int[]) array;
                int[] newArrayInt = new int[newLength];
                System.arraycopy(oldArray, 0, newArrayInt, 0, oldArray.length);
