private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    // Find the position of the highest set bit, which is floor(log2(n)) + 1
    // For n=1, returns 1; for n=2, returns 2; for n=3, returns 2; etc.
    int count = 0;
    int temp = n;
    while (temp > 0) {
        count++;
        temp >>= 1;
    }
    return count;
}
