    private int removeUnusedNodesRecursive(Node node) {
        int removedCount = 0;
        if (node == null) {
            return removedCount;
        }
        // Recursively process child nodes
        List<Node> children = node.getChildren();
        if (children != null) {
            Iterator<Node> iterator = children.iterator();
            while (iterator.hasNext()) {
                Node child = iterator.next();
                int childRemoved = removeUnusedNodesRecursive(child);
                removedCount += childRemoved;
                if (!child.isActive()) {
                    iterator.remove();
                    removedCount++;
                }
            }
        }
        return removedCount;
    }
