        Set<V> predecessors = graph.incomingNeighbors(vertex);
        for (V pred : predecessors) {
            double weight = graph.getEdgeWeight(pred, vertex);
            if (weight != 0.0) {
                sum += weight;
            }
        }
    }
    return sum;
}

public double vertexWeight(Set<V> v) {
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    double weightSum = 0.0;
    for (E e : edgeSet) {
        if (v.contains(e.getHead())) {
            weightSum += e.getWeight();
        }
    }
    return weightSum;
}

public double vertexWeight(Set<V> v) {
    double sum = 0.0;
    for (V vertex : v) {
        for (E edge : graph.inEdges(vertex)) {
            sum += weight(edge);
        }
    }
    return sum;
}

