public int appendLoopOnAppenders(LoggingEvent event) {
    int total = 0;
    AppenderIterator iterator = ((AppenderSkeleton) this).getAllAppenders();
    try {
        while (iterator.hasNext()) {
            Appender appender = iterator.next();
            appender.doAppend(event);
            total++;
        }
    } finally {
        if (iterator != null) {
            iterator.close();
        }
    }
    return total;
}

