protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }

    int n = tour.size();
    if (n == 0) {
        return null;
    }

    Map<V, Set<E>> adjacencyMap = new HashMap<>();
    for (V vertex : graph.getVertices()) {
        adjacencyMap.put(vertex, graph.getEdges(vertex));
    }

    V startVertex = null;
    for (E edge : tour) {
        Set<V> endpoints = graph.getEndpoints(edge);
        if (endpoints != null && !endpoints.isEmpty()) {
            startVertex = endpoints.iterator().next();
            break;
        }
    }

    if (startVertex == null) {
        return null;
    }

    List<V> path = new ArrayList<>();
    List<E> pathEdges = new ArrayList<>();

    V currentVertex = startVertex;
    path.add(currentVertex);

    Set<E> usedEdges = new HashSet<>(tour);

    for (int i = 0; i < n; i++) {
        // Find an unused edge from currentVertex
        boolean edgeFound = false;
        for (E edge : graph.getEdges(currentVertex)) {
            if (usedEdges.contains(edge)) {
                Set<V> endpoints = graph.getEndpoints(edge);
                V otherVertex = endpoints.iterator().next();
                if (endpoints.size() > 1) {
                    otherVertex = endpoints.iterator().next();
                    endpoints.iterator().next(); // skip one
                }
                if (!otherVertex.equals(currentVertex)) {
                    path.add(otherVertex);
                    pathEdges.add(edge);
                    usedEdges.remove(edge);
                    currentVertex = otherVertex;
                    edgeFound = true;
                    break;
                }
            }
        }
        if (!edgeFound) {
            // If we can't find an edge, maybe we've completed the tour
            break;
        }
    }

    // If the path doesn't return to the start and we have exactly n nodes, it's a cycle
    // but the tour should close. Let's check if we need to handle that.

    // A more robust approach: use a stack-based Euler tour on the subgraph defined by the edges in tour
    // But given the method context (likely part of a TSP solver), a simple path reconstruction might be expected.

    // Let's try a cleaner algorithm for reconstruction assuming 'tour' edges form a single cycle
    // (which is typical for TSP tours).
    Map<V, List<V>> nextVertices = new HashMap<>();
    for (V v : graph.getVertices()) {
        nextVertices.put(v, new ArrayList<>());
    }
    for (E e : tour) {
        Set<V> ends = graph.getEndpoints(e);
        if (ends.size() == 2) {
            Iterator<V> it = ends.iterator();
            V u = it.next();
            V w = it.next();
            nextVertices.get(u).add(w);
            nextVertices.get(w).add(u);
        }
    }

    V start = null;
    for (V v : nextVertices.keySet()) {
        if (!nextVertices.get(v).isEmpty()) {
            start = v;
            break;
        }
    }

    if (start == null) {
        return null;
    }

    if (graph instanceof DirectedGraph) {
        // Direct graph: find start with out-degree 1 in the tour subgraph, or use first edge
        // For TSP tour on directed graph, each vertex has exactly one outgoing edge in tour.
        Map<V, V> nextInToured = new HashMap<>();
        for (E e : tour) {
            Set<V> ends = graph.getEndpoints(e);
            // Directed edge endpoints: [source, target]
            if (ends.size() == 2) {
                Iterator<V> it = ends.iterator();
                V source = it.next();
                V target = it.next();
                nextInToured.put(source, target);
            }
        }
        path.clear();
        pathEdges.clear();
        V cur = start;
        Set<E> edgesInPath = new HashSet<>();
        for (int i = 0; i < n; i++) {
            path.add(cur);
            V next = nextInToured.get(cur);
            if (next == null) {
                break;
            }
            // Find the edge between cur and next in tour
            for (E e : graph.getEdges(cur, next)) {
                if (tour.contains(e)) {
                    pathEdges.add(e);
                    break;
                }
            }
            cur = next;
        }
    } else {
        // Undirected graph
        path.clear();
        pathEdges.clear();
        V cur = start;
        path.add(cur);
        Set<E> edgeSetLocal = new HashSet<>(tour);
        for (int i = 0; i < n; i++) {
            V next = null;
            E edge = null;
            for (E e : graph.getEdges(cur)) {
                if (edgeSetLocal.contains(e)) {
                    Set<V> ends = graph.getEndpoints(e);
                    if (ends.size() == 2) {
                        Iterator<V> it = ends.iterator();
                        V u = it.next();
                        V w = it.next();
                        V other = u.equals(cur) ? w : u;
                        if (!other.equals(cur)) {
                            next = other;
                            edge = e;
                            break;
                        }
                    }
                }
            }
            if (next == null) {
                break;
            }
            path.add(next);
            pathEdges.add(edge);
            edgeSetLocal.remove(edge);
            cur = next;
        }
    }

    if (path.isEmpty()) {
        return null;
    }

    // If the path is a tour (cycle), the last vertex should be the start vertex.
    // Some GraphPath implementations expect the path to not repeat the start at the end.
    // Check if the last node equals the first node.
    if (path.size() > 1 && path.get(0).equals(path.get(path.size() - 1))) {
        // It's a cycle represented with start==end. Depending on GraphPath convention,
        // we might remove the last duplicate.
        // GraphPath in JGraphT: "A graph path is a sequence of vertices in a graph where two consecutive vertices 
        // are adjacent to each other in the graph. The vertices in a path are distinct."
        // So we should remove the last vertex if it equals the first.
        // But wait, if it's a tour (cycle), then we go from start to ... to start.
