int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }

    for (Symbol sym : constantPool) {
        if (sym.getKind() == CONSTANT_NameAndType
                && name.equals(sym.getName())
                && descriptor.equals(sym.getDescriptor())) {
            return sym.getId();
        }
    }

    Symbol symbol = new Symbol(name, descriptor);
    symbol.setKind(CONSTANT_NameAndType);
    constantPool.add(symbol);
    return symbol.getId();
}
