private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node to unlink cannot be null");
    }

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // Node is the head
        head = next;
        if (head != null) {
            head.prev = null;
        }
    } else {
        prev.next = next;
    }

    if (next == null) {
        // Node is the tail
        tail = prev;
        if (tail != null) {
            tail.next = null;
        }
    } else {
        next.prev = prev;
    }

    // Clear references to help garbage collection
    node.prev = null;
    node.next = null;
    node.element = null;

    size--;

    return size == 0;
}

