private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0L;
    long runningSum = 0L;

    // Traverse from end to start
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        if (value == null) {
            throw new IllegalArgumentException("Bounds list cannot contain null values at index " + i);
        }
        runningSum += value;
        suffixSum.add((int) runningSum);
        totalSum += value;
    }

    // Reverse to get the proper order
    Collections.reverse(suffixSum);

    return Pair.of(suffixSum, totalSum);
}

