        throw new IllegalArgumentException("Array must not be null");
    }
    int n = arr.length;
    if (from < 0 || from >= n) {
        throw new IllegalArgumentException("from index is out of bounds");
    }
    if (to < 0 || to >= n) {
        throw new IllegalArgumentException("to index is out of bounds");
    }
    if (from > to) {
