private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }

    // Traverse all nodes from the source list
    ListNode<E> current = list.head;
    while (current != null && current != list.tail) {
        // Remove the current node from the source list (atomically per node)
        ListNode<E> next = current.next;
        list.removeListNode(current);
        // Add the node to this list
        addListNode(current);
        current = next;
    }
    // If list is empty (head == tail == null), nothing to move
