        throw new IllegalArgumentException("map must not be null");
    }

    // Get all writable property descriptors from the source map
    BeanMapWritableBean sourceBean = map.getWritableBean();
    if (sourceBean == null) {
        return;
    }

    // Get the writable property descriptor information
    java.beans.BeanInfo sourceBeanInfo = map.getBeanInfo();
    if (sourceBeanInfo == null) {
        return;
    }

    java.beans.PropertyDescriptor[] sourceProps = sourceBeanInfo.getPropertyDescriptors();
    java.beans.BeanInfo targetBeanInfo = this.getBeanInfo();
    if (targetBeanInfo == null) {
        return;
    }

    for (java.beans.PropertyDescriptor sourceProp : sourceProps) {
        String propName = sourceProp.getName();

        // Skip class property and non-writable properties
        if ("class".equals(propName) || !sourceProp.getWriteMethod() != null) {
            continue;
        }

        // Check if target has a writable property with the same name
        java.beans.PropertyDescriptor targetProp = targetBeanInfo
            .getPropertyDescriptorMap().get(propName);
        if (targetProp == null || targetProp.getWriteMethod() == null) {
            continue;
        }

        try {
            Object value = sourceProp.getReadMethod().invoke(sourceBean);
            if (value != null) {
                Map thisMap = this.getTable();
                if (thisMap != null) {
                    thisMap.put(propName, value);
                }
            }
        } catch (Exception e) {
            // Ignore errors and continue processing other properties
            continue;
        }
    }
}

