    private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
        List<Pair<List<Pair<Integer,Integer>>, E>> result = new ArrayList<>();

        // Iterate over all edges in the graph
        for (E edge : this.edges()) {
            int u = edge.getS().getId();
            int v = edge.getT().getId();

            // Get the neighborhood of edge e = (u, v)
            Set<Integer> neighborhood = new HashSet<>();

            // Collect all vertices that are neighbors to both u and v (common neighbors)
            for (E e1 : this.edges().get(u)) {
                if (e1.getT().getId() != v) {
                    neighborhood.add(e1.getT().getId());
                }
            }

            List<Pair<Integer, Integer>> commonNeighbors = new ArrayList<>(neighborhood);

            // If there are no common neighbors, the edge is a separator by itself? 
            // Actually, minimal separator for an edge in a graph context usually 
            // involves finding induced complete subgraphs in the intersection of neighborhoods.
            // Following standard algorithms (like Small's algorithm), we need to find
            // maximal cliques in the intersection G[N(v)\{u}] and G[N(u)\{v}] that are also 
            // subsets of the other neighborhood.

            // Let's use a simplified approach: Find all minimal separators by checking 
            // combinations of common neighbors. For each subset S of common neighbors, 
            // check if S is a separator (u and v disconnected in G-S) and minimal.
            // This is exponential, so for a production method, we'd use a smarter algorithm.
            // Given the context of "global separator list" and potential duplicates, 
            // a common method is to use the algorithm from Murota or similar.

            // Here is a plausible implementation based on finding minimal separators 
            // in the neighborhood by checking connectivity

            List<List<Pair<Integer, Integer>>> separators = new ArrayList<>();

            // Get unique neighbors for u and v
            Set<Integer> nbrU = new HashSet<>();
            Set<Integer> nbrV = new HashSet<>();

            for (E e1 : this.edges().get(u)) {
                if (e1.getT().getId() != v) {
                    nbrU.add(e1.getT().getId());
                }
            }
            for (E e1 : this.edges().get(v)) {
                if (e1.getS().getId() != u) {
                    nbrV.add(e1.getS().getId());
                }
            }

            // Intersection
            Set<Integer> intersection = new HashSet<>(nbrU);
            intersection.retainAll(nbrV);

            // We need to find all minimal separators in this intersection.
            // A set S is a separator if it separates u and v.
            // S is minimal if no proper subset of S is a separator.
            // Standard approach: Find all maximal cliques in the neighborhood, 
            // then minimal separators are subsets of these cliques.

            // For simplicity, let's generate all subsets of intersection 
            // (only feasible for small intersections) and check minimality.

            int n = intersection.size();
            int[] arr = new int[n];
            int idx = 0;
            for (Integer id : intersection) {
                arr[idx++] = id;
            }

            for (int mask = 1; mask < (1 << n); mask++) {
                List<Pair<Integer, Integer>> s = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        s.add(Pair.of(u, arr[i])); // representing the vertex id
                    }
                }

                // Check if s separates u and v
                // Create a BFS/DFS queue excluding vertices in s (except u and v)
                Set<Integer> removed = new HashSet<>();
                for (Pair<Integer, Integer> p : s) {
                    removed.add(p.getT()); // p.getT() is the vertex id from intersection
                }

                // BFS from u
                Set<Integer> visited = new HashSet<>();
                Deque<Integer> queue = new ArrayDeque<>();
                queue.offer(u);
                visited.add(u);
                boolean connected = false;

                while (!queue.isEmpty()) {
                    int curr = queue.poll();
                    if (curr == v) {
                        connected = true;
                        break;
                    }
                    for (E e1 : this.edges().get(curr)) {
                        int nextId = e1.getT().getId();
                        if (!visited.contains(nextId) && !removed.contains(nextId)) {
                            visited.add(nextId);
                            queue.offer(nextId);
                        }
                    }
                }

                if (!connected) {
                    // Check minimality: no proper subset of s is a separator
                    boolean isMinimal = true;
                    for (int subMask = (mask - 1); subMask > 0; subMask = (subMask - 1) & mask) {
                        if ((subMask & mask) == subMask) {
                            List<Pair<Integer, Integer>> subS = new ArrayList<>();
                            for (int i = 0; i < n; i++) {
                                if ((subMask & (1 << i)) != 0) {
                                    subS.add(Pair.of(u, arr[i]));
                                }
                            }

                            Set<Integer> subRemoved = new HashSet<>();
                            for (Pair<Integer, Integer> p : subS) {
                                subRemoved.add(p.getT());
                            }

                            Set<Integer> subVisited = new HashSet<>();
                            Deque<Integer> subQueue = new ArrayDeque<>();
                            subQueue.offer(u);
                            subVisited.add(u);
                            boolean subConnected = false;

                            while (!subQueue.isEmpty()) {
                                int curr = subQueue.poll();
                                if (curr == v) {
                                    subConnected = true;
                                    break;
                                }
                                for (E e1 : this.edges().get(curr)) {
                                    int nextId = e1.getT().getId();
                                    if (!subVisited.contains(nextId) && !subRemoved.contains(nextId)) {
                                        subVisited.add(nextId);
                                        subQueue.offer(nextId);
                                    }
                                }
                            }

                            if (!subConnected) {
                                isMinimal = false;
                                break;
                            }
                        }
                    }

                    if (isMinimal) {
                        separators.add(s);
                    }
                }
            }

            // Add all minimal separators for this edge to the result
            if (!separators.isEmpty()) {
                for (List<Pair<Integer, Integer>> sep : separators) {
                    result.add(Pair.of(sep, edge));
                }
            }
        }

        return result;
