        throw new IllegalArgumentException("Scroll pane must not be null");
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        throw new IllegalArgumentException("Row index is out of bounds: " + row + " (valid range: 0 to " + (rowCount - 1) + ")");
