    public void abbreviate(final int nameStart, final StringBuffer buf) {
        // Initialize a flag to track if the previous character was a letter
        boolean prevCharWasLetter = false;

        // Get the length of the name
        final int nameLength = name.length();

        // Loop through the name from nameStart to the end
        for (int i = nameStart; i < nameLength; i++) {
            final char currentChar = name.charAt(i);

            // Check if the current character is a letter
            if (Character.isLetter(currentChar)) {
                if (!prevCharWasLetter) {
                    // If the previous character was not a letter, append the uppercase version of the current character
                    buf.append(Character.toUpperCase(currentChar));
                    prevCharWasLetter = true;
                }
                // If the previous character was a letter, skip appending the current character
            } else {
                // If the current character is not a letter, append it as is and reset the flag
                buf.append(currentChar);
                prevCharWasLetter = false;
            }
        }
    }
